"""Synthetic, xlsx-shaped HSE observation/incident workbook fixture — SIE
Real Enterprise Dataset Evaluation v0.1.

**This is SYNTHETIC data. It is not, and must never be described as,
real customer or enterprise data.** No row, name, project, or narrative
below is derived from the real workbook this milestone evaluated — every
value here is fabricated, deterministic, and built purely from this
module's own literals (mirroring `tests/fixtures/messy_enterprise_dataset.py`'s
own "synthetic, not real" discipline for the milestone-3 harness).

What makes this fixture worth having, rather than reusing
`messy_enterprise_dataset.py`'s already-canonical `RawSafetyEventPayload`
objects: `app/validation/real_dataset_loader.py` is a **workbook-parsing**
layer, and several of its own documented behaviors can only be exercised
by an actual `.xlsx` file with the real workbook's own structural
quirks reproduced:

* Sheet names carrying a trailing space (`"Incident "`, `"Observation "`).
* The Incident sheet's own `"Date "` header (trailing space) vs. the
  Observation sheet's `"Date"` (no trailing space).
* The Observation sheet's literal **duplicate** `"Status"` header (two
  columns, both named exactly `"Status"`).
* A raw `Incident Type` term that maps cleanly against the existing,
  unmodified `terminology_mapping.py` alias table (`"Injury"`) alongside
  one that does not (`"NearMiss"`, camelCase, no separator) — a genuine
  MAPPED-vs-UNKNOWN split, not a guess either way.
* Rows with a missing `Document No` / missing `Date` (never dropped by
  the loader — see its own docstring), an exact-duplicate `Document No`,
  a future-dated row, and a narrative field carrying a fabricated
  (synthetic) personal name, to exercise the PII-preservation-but-never-
  read-by-features guarantee.
* A wholly blank spreadsheet row (must be skipped, never counted or
  mapped) between real data rows, exactly as a real export commonly has.

`build_synthetic_workbook()` writes the file to a caller-supplied path
(a test's own tmp_path — never this repository) and returns
`SyntheticWorkbookCharacteristics`, the by-hand-counted expectations a
test asserts against directly.
"""

from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime, timedelta, timezone
from pathlib import Path

from openpyxl import Workbook

SYNTHETIC_LABEL = (
    "SYNTHETIC — xlsx-shaped fixture data generated by "
    "tests/fixtures/real_dataset_xlsx_fixture.py. Not real customer or "
    "enterprise data. Passing this fixture's tests does not constitute "
    "validation against real customer data."
)

# Deliberately mirrors the real workbook's own project-name shape: the
# Incident sheet's projects are a *subset* of the Observation sheet's own
# (the Observation sheet also covers project(s) with no incident on
# record at all) -- see real_dataset_evaluation.py's own project
# reconciliation note.
INCIDENT_PROJECTS = ("Synthetic Site Alpha", "Synthetic Site Beta")
OBSERVATION_ONLY_PROJECT = "Synthetic Site Gamma"  # observation-only -- no incidents

SYNTHETIC_PII_NAME = "Jordan Testperson"  # fabricated; used only to prove PII fields are preserved, never guessed away


@dataclass
class SyntheticWorkbookCharacteristics:
    incident_data_row_count: int  # non-blank data rows the loader should count
    observation_data_row_count: int
    incident_projects: set
    observation_projects: set
    mapped_incident_type_term: str  # resolves against the existing, unmodified alias table
    unknown_incident_type_term: str  # does not
    duplicate_incident_document_no: str
    duplicate_observation_document_no: str
    missing_document_no_incident_rows: int
    missing_date_incident_rows: int
    missing_document_no_observation_rows: int
    missing_date_observation_rows: int
    future_timestamp_incident_rows: int
    pii_bearing_incident_document_no: str
    pii_bearing_observation_document_no: str


def build_synthetic_workbook(path: str | Path, base_time: datetime | None = None) -> SyntheticWorkbookCharacteristics:
    base_time = base_time or datetime.now(timezone.utc)

    def d(days_ago: int) -> datetime:
        return (base_time - timedelta(days=days_ago)).replace(tzinfo=None)

    wb = Workbook()

    # --- Incident sheet -----------------------------------------------------------------------
    # Sheet name and "Date " header both carry the real workbook's own
    # trailing-space quirk -- the loader must normalize both.
    inc_ws = wb.active
    inc_ws.title = "Incident "
    incident_headers = [
        "Document No", "Date ", "Project", "Incident Type", "Description", "PeopleInvolved",
        "WitnessStatement", "ImmediateActionTaken", "Root Cause Analysis", "Corrective Action",
        "Preventive Action", "Recommendation", "Conclusion", "Reported By",
    ]
    inc_ws.append(incident_headers)

    # Clean, mapped term ("Injury" -> matches the existing alias table exactly).
    inc_ws.append([
        "SYN-IC-0001", d(20), INCIDENT_PROJECTS[0], "Injury", "Synthetic incident description one.",
        "N/A", "N/A", "First aid administered.", "N/A", "N/A", "N/A", "N/A", "N/A", "Synthetic Reporter A",
    ])
    # Unknown term ("NearMiss", camelCase -- does not match "near miss" in the existing table).
    inc_ws.append([
        "SYN-IC-0002", d(15), INCIDENT_PROJECTS[1], "NearMiss", "Synthetic incident description two.",
        "N/A", "N/A", "N/A", "N/A", "N/A", "N/A", "N/A", "N/A", "Synthetic Reporter B",
    ])
    # Blank row -- must be skipped entirely, never counted or mapped.
    inc_ws.append([None] * len(incident_headers))
    # Missing Document No -- never dropped by the loader; still a payload with source_record_id=None.
    inc_ws.append([
        None, d(12), INCIDENT_PROJECTS[0], "Injury", "Synthetic incident, no document number.",
        "N/A", "N/A", "N/A", "N/A", "N/A", "N/A", "N/A", "N/A", None,
    ])
    # Missing Date -- likewise never dropped.
    inc_ws.append([
        "SYN-IC-0004", None, INCIDENT_PROJECTS[0], "Injury", "Synthetic incident, no date.",
        "N/A", "N/A", "N/A", "N/A", "N/A", "N/A", "N/A", "N/A", None,
    ])
    # Exact-duplicate Document No (two distinct rows sharing one identifier) -- duplicate handling.
    inc_ws.append([
        "SYN-IC-0005", d(8), INCIDENT_PROJECTS[1], "Injury", "Synthetic incident, duplicate id, first.",
        "N/A", "N/A", "N/A", "N/A", "N/A", "N/A", "N/A", "N/A", "Synthetic Reporter C",
    ])
    inc_ws.append([
        "SYN-IC-0005", d(8), INCIDENT_PROJECTS[1], "Injury", "Synthetic incident, duplicate id, second.",
        "N/A", "N/A", "N/A", "N/A", "N/A", "N/A", "N/A", "N/A", "Synthetic Reporter C",
    ])
    # Future timestamp.
    inc_ws.append([
        "SYN-IC-0006", base_time.replace(tzinfo=None) + timedelta(days=30), INCIDENT_PROJECTS[0], "Injury",
        "Synthetic incident, future-dated.", "N/A", "N/A", "N/A", "N/A", "N/A", "N/A", "N/A", "N/A", None,
    ])
    # A row carrying a fabricated personal name in narrative fields --
    # proves the loader preserves it (never strips/guesses it away) while
    # the evaluation report/feature engineering must never surface it.
    inc_ws.append([
        "SYN-IC-0007", d(5), INCIDENT_PROJECTS[0], "Injury",
        f"Synthetic incident involving {SYNTHETIC_PII_NAME} on site.", SYNTHETIC_PII_NAME,
        f"Witness statement naming {SYNTHETIC_PII_NAME}.", "N/A", "N/A", "N/A", "N/A", "N/A", "N/A",
        SYNTHETIC_PII_NAME,
    ])

    # --- Observation sheet ----------------------------------------------------------------------
    obs_ws = wb.create_sheet("Observation ")
    # Literal duplicate "Status" header -- position 5 (primary, business
    # lifecycle) and position 10 (secondary, never merged with the first).
    observation_headers = [
        "Document No", "Date", "Project Name", "Category", "Type", "Status", "Finding",
        "Recommendation", "Action Taken", "Comment", "Status",
    ]
    obs_ws.append(observation_headers)

    obs_ws.append([
        "SYN-OB-0001", d(18), INCIDENT_PROJECTS[0], "Housekeeping", "Routine", "Closed",
        "Synthetic finding one.", "Clear the walkway.", "Walkway cleared.", "N/A", "REVIEW REQUIRED",
    ])
    obs_ws.append([
        "SYN-OB-0002", d(16), OBSERVATION_ONLY_PROJECT, "Unsafe Act", "Behavioral", "Open",
        "Synthetic finding two.", "Retrain staff.", "N/A", "Pending retraining.", "OK",
    ])
    # Blank row.
    obs_ws.append([None] * len(observation_headers))
    # Missing Document No.
    obs_ws.append([
        None, d(10), INCIDENT_PROJECTS[1], "PPE Compliance", "Routine", "Closed",
        "Synthetic finding, no document number.", "N/A", "N/A", "N/A", "REVIEW REQUIRED",
    ])
    # Missing Date.
    obs_ws.append([
        "SYN-OB-0004", None, INCIDENT_PROJECTS[1], "PPE Compliance", "Routine", "Closed",
        "Synthetic finding, no date.", "N/A", "N/A", "N/A", "REVIEW REQUIRED",
    ])
    # Exact-duplicate Document No.
    obs_ws.append([
        "SYN-OB-0005", d(6), OBSERVATION_ONLY_PROJECT, "Housekeeping", "Routine", "Open",
        "Synthetic finding, duplicate id, first.", "N/A", "N/A", "N/A", "OK",
    ])
    obs_ws.append([
        "SYN-OB-0005", d(6), OBSERVATION_ONLY_PROJECT, "Housekeeping", "Routine", "Open",
        "Synthetic finding, duplicate id, second.", "N/A", "N/A", "N/A", "OK",
    ])
    # A row carrying a fabricated personal name in a narrative field.
    obs_ws.append([
        "SYN-OB-0006", d(3), INCIDENT_PROJECTS[0], "Unsafe Act", "Behavioral", "Closed",
        f"Synthetic finding noting {SYNTHETIC_PII_NAME} was present.", "N/A", "N/A",
        f"Discussed with {SYNTHETIC_PII_NAME}.", "REVIEW REQUIRED",
    ])

    wb.save(str(path))

    return SyntheticWorkbookCharacteristics(
        incident_data_row_count=8,  # 9 appended rows minus the 1 deliberately blank row
        observation_data_row_count=7,  # 8 appended rows minus the 1 deliberately blank row
        incident_projects=set(INCIDENT_PROJECTS),
        observation_projects=set(INCIDENT_PROJECTS) | {OBSERVATION_ONLY_PROJECT},
        mapped_incident_type_term="Injury",
        unknown_incident_type_term="NearMiss",
        duplicate_incident_document_no="SYN-IC-0005",
        duplicate_observation_document_no="SYN-OB-0005",
        missing_document_no_incident_rows=1,
        missing_date_incident_rows=1,
        missing_document_no_observation_rows=1,
        missing_date_observation_rows=1,
        future_timestamp_incident_rows=1,
        pii_bearing_incident_document_no="SYN-IC-0007",
        pii_bearing_observation_document_no="SYN-OB-0006",
    )
